-- Alpha 0.3: Startbestand mit 100 alltagstauglichen Familiengerichten
-- Zutaten bleiben im gleichen JSON-Array-Format wie die bestehende Anwendung.
-- Sicher erneut ausführbar: vorhandene Rezepte mit gleichem slug werden aktualisiert.

on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  category = excluded.category,
  prep_minutes = excluded.prep_minutes,
  cook_minutes = excluded.cook_minutes,
  servings = excluded.servings,
  ingredients = excluded.ingredients,
  instructions = excluded.instructions,
  is_published = excluded.is_published,
  updated_at = now();

-- Kontrolle: Anzahl der veröffentlichten Rezepte
select count(*) as published_recipe_count
from public.recipe_catalog
where is_published = true;
